import hashlib, hmac
import numpy as np

def pack(p1, p2, p3, origin=b"SovereignOriginSeed2026"):
    grid = np.zeros((9, 9), dtype=np.float64)
    prk = hmac.new(b"SovereignOrigin", origin, hashlib.sha256).digest()
    key = hmac.new(prk, b"ResidualScript-Offset\x01", hashlib.sha256).digest()
    off = hmac.new(key, (1).to_bytes(8, "big") + b"offset", hashlib.sha256).digest()
    grid[3, 3], grid[3, 4], grid[3, 5] = p1, p2, p3
    grid[4, 3], grid[4, 4], grid[4, 5] = -p1, -p2, -p3
    grid[5, 3] = 0.0
    grid[5, 4] = float(int.from_bytes(off[:8], "big")) / 1e19
    grid[5, 5] = 1.0
    return grid

def complement_row(grid):
    return grid[4, 3:6].copy()

def checksum_sum(grid):
    return float((grid[3, 3:6] + grid[4, 3:6]).sum())

def block_id(grid):
    return hashlib.sha256(grid.tobytes()).hexdigest()

